import{_ as d,W as l,s as i,u as g,I as n,ah as p,w as s,Z as t,A as e}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const B=JSON.parse('{"title":"如何在 Ubuntu 上安装 MongoDB | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上安装 MongoDB | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上安装 MongoDB | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上安装 MongoDB | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190304 How to Install MongoDB on Ubuntu","title":"如何在 Ubuntu 上安装 MongoDB","tag":"201908"},"relativePath":"201908/20190304 How to Install MongoDB on Ubuntu.md","filePath":"[post].md"}'),u={name:"201908/20190304 How to Install MongoDB on Ubuntu.md"};function r(b,o,c,m,h,v){const a=l("Link");return g(),i("div",null,[o[25]||(o[25]=n("h1",{id:"如何在-ubuntu-上安装-mongodb",tabindex:"-1"},[s("如何在 Ubuntu 上安装 MongoDB "),n("a",{class:"header-anchor",href:"#如何在-ubuntu-上安装-mongodb","aria-label":"Permalink to 如何在 Ubuntu 上安装 MongoDB"},"​")],-1)),o[26]||(o[26]=n("blockquote",null,[n("p",null,"本教程介绍了在 Ubuntu 和基于 Ubuntu 的 Linux 发行版上安装 MongoDB 的两种方法。")],-1)),n("p",null,[t(a,{href:"https://www.mongodb.com/"},{default:e(()=>o[0]||(o[0]=[s("MongoDB")])),_:1}),o[1]||(o[1]=s(" 是一个越来越流行的自由开源的 NoSQL 数据库，它将数据存储在类似 JSON 的灵活文档集中，这与 SQL 数据库中常见的表格形式形成对比。"))]),o[27]||(o[27]=p(`<p>你很可能发现在现代 Web 应用中使用 MongoDB。它的文档模型使得使用各种编程语言能非常直观地访问和处理它。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/mongodb-ubuntu.jpeg?resize=800%2C450&amp;ssl=1" alt="mongodb Ubuntu"></p><p>在本文中，我将介绍两种在 Ubuntu 上安装 MongoDB 的方法。</p><h3 id="在基于-ubuntu-的发行版上安装-mongodb" tabindex="-1">在基于 Ubuntu 的发行版上安装 MongoDB <a class="header-anchor" href="#在基于-ubuntu-的发行版上安装-mongodb" aria-label="Permalink to 在基于 Ubuntu 的发行版上安装 MongoDB">​</a></h3><ol><li>使用 Ubuntu 仓库安装 MongoDB。简单但不是最新版本的 MongoDB</li><li>使用其官方仓库安装 MongoDB。稍微复杂，但你能得到最新版本的 MongoDB。</li></ol><p>第一种安装方法更容易，但如果你计划使用官方支持的最新版本，那么我建议使用第二种方法。</p><p>有些人可能更喜欢使用 snap 包。Ubuntu 软件中心提供了 snap，但我不建议使用它们，因为他们现在已经过期了，因此我这里不会提到。</p><h3 id="方法-1-从-ubuntu-仓库安装-mongodb" tabindex="-1">方法 1：从 Ubuntu 仓库安装 MongoDB <a class="header-anchor" href="#方法-1-从-ubuntu-仓库安装-mongodb" aria-label="Permalink to 方法 1：从 Ubuntu 仓库安装 MongoDB">​</a></h3><p>这是在系统中安装 MongoDB 的简便方法，你只需输入一个命令即可。</p><h4 id="安装-mongodb" tabindex="-1">安装 MongoDB <a class="header-anchor" href="#安装-mongodb" aria-label="Permalink to 安装 MongoDB">​</a></h4><p>首先，确保你的包是最新的。打开终端并输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt upgrade -y</span></span></code></pre></div><p>继续安装 MongoDB：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install mongodb</span></span></code></pre></div><p>这就完成了！MongoDB 现在安装到你的计算机上了。</p><p>MongoDB 服务应该在安装时自动启动，但要检查服务状态：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl status mongodb</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/02/mongodb_check_status.jpg?fit=800%2C574&amp;ssl=1" alt="Check if the MongoDB service is running."></p><p>你可以看到该服务是<strong>活动</strong>的。</p><h4 id="运行-mongodb" tabindex="-1">运行 MongoDB <a class="header-anchor" href="#运行-mongodb" aria-label="Permalink to 运行 MongoDB">​</a></h4><p>MongoDB 目前是一个 systemd 服务，因此我们使用 <code>systemctl</code> 来检查和修改它的状态，使用以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl status mongodb</span></span>
<span class="line"><span>sudo systemctl stop mongodb</span></span>
<span class="line"><span>sudo systemctl start mongodb</span></span>
<span class="line"><span>sudo systemctl restart mongodb</span></span></code></pre></div><p>你也可以修改 MongoDB 是否自动随系统启动（默认：启用）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl disable mongodb</span></span>
<span class="line"><span>sudo systemctl enable mongodb</span></span></code></pre></div><p>要开始使用（创建和编辑）数据库，请输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mongo</span></span></code></pre></div>`,26)),n("p",null,[o[3]||(o[3]=s("这将启动 ")),o[4]||(o[4]=n("strong",null,"mongo shell",-1)),o[5]||(o[5]=s("。有关查询和选项的详细信息，请查看")),t(a,{href:"https://docs.mongodb.com/manual/tutorial/getting-started/"},{default:e(()=>o[2]||(o[2]=[s("手册")])),_:1}),o[6]||(o[6]=s("。"))]),o[28]||(o[28]=p(`<p>**注意：**根据你计划使用 MongoDB 的方式，你可能需要调整防火墙。不过这超出了本篇的内容，并且取决于你的配置。</p><h4 id="卸载-mongodb" tabindex="-1">卸载 MongoDB <a class="header-anchor" href="#卸载-mongodb" aria-label="Permalink to 卸载 MongoDB">​</a></h4><p>如果你从 Ubuntu 仓库安装 MongoDB 并想要卸载它（可能要使用官方支持的方式安装），请输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl stop mongodb</span></span>
<span class="line"><span>sudo apt purge mongodb</span></span>
<span class="line"><span>sudo apt autoremove</span></span></code></pre></div><p>这应该会完全卸载 MongoDB。确保<strong>备份</strong>你可能想要保留的任何集合或文档，因为它们将被删除！</p><h3 id="方法-2-在-ubuntu-上安装-mongodb-社区版" tabindex="-1">方法 2：在 Ubuntu 上安装 MongoDB 社区版 <a class="header-anchor" href="#方法-2-在-ubuntu-上安装-mongodb-社区版" aria-label="Permalink to 方法 2：在 Ubuntu 上安装 MongoDB 社区版">​</a></h3><p>这是推荐的安装 MongoDB 的方法，它使用包管理器。你需要多打几条命令，对于 Linux 新手而言，这可能会感到害怕。</p><p>但没有什么可怕的！我们将一步步说明安装过程。</p><h4 id="安装-mongodb-1" tabindex="-1">安装 MongoDB <a class="header-anchor" href="#安装-mongodb-1" aria-label="Permalink to 安装 MongoDB">​</a></h4><p>由 MongoDB Inc. 维护的包称为 <code>mongodb-org</code>，而不是 <code>mongodb</code>（这是 Ubuntu 仓库中包的名称）。在开始之前，请确保系统上未安装 <code>mongodb</code>。因为包之间会发生冲突。让我们开始吧！</p><p>首先，我们必须导入公钥：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-key adv --keyserver hkp://keyserver.ubuntu.com:80 --recv 9DA31620334BD75D9DCB49F368818C72E52529D4</span></span></code></pre></div><p>现在，你需要在源列表中添加一个新的仓库，以便你可以安装 MongoDB 社区版并获得自动更新：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo &quot;deb [ arch=amd64 ] https://repo.mongodb.org/apt/ubuntu $(lsb_release -cs)/mongodb-org/4.0 multiverse&quot; | sudo tee /etc/apt/sources.list.d/mongodb-org-4.0.list</span></span></code></pre></div><p>要安装 <code>mongodb-org</code>，我们需要更新我们的包数据库，以便系统知道可用的新包：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>现在你可以安装<strong>最新稳定版</strong>的 MongoDB：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install -y mongodb-org</span></span></code></pre></div><p>或者某个<strong>特定版本</strong>（在 <code>=</code> 后面修改版本号）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install -y mongodb-org=4.0.6 mongodb-org-server=4.0.6 mongodb-org-shell=4.0.6 mongodb-org-mongos=4.0.6 mongodb-org-tools=4.0.6</span></span></code></pre></div><p>如果你选择安装特定版本，请确保在所有位置都修改了版本号。如果你修改了 <code>mongodb-org=4.0.6</code>，你将安装最新版本。</p><p>默认情况下，使用包管理器（<code>apt-get</code>）更新时，MongoDB 将更新为最新的版本。要阻止这种情况发生（并冻结为已安装的版本），请使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo &quot;mongodb-org hold&quot; | sudo dpkg --set-selections</span></span>
<span class="line"><span>echo &quot;mongodb-org-server hold&quot; | sudo dpkg --set-selections</span></span>
<span class="line"><span>echo &quot;mongodb-org-shell hold&quot; | sudo dpkg --set-selections</span></span>
<span class="line"><span>echo &quot;mongodb-org-mongos hold&quot; | sudo dpkg --set-selections</span></span>
<span class="line"><span>echo &quot;mongodb-org-tools hold&quot; | sudo dpkg --set-selections</span></span></code></pre></div><p>你现在已经成功安装了 MongoDB！</p><h4 id="配置-mongodb" tabindex="-1">配置 MongoDB <a class="header-anchor" href="#配置-mongodb" aria-label="Permalink to 配置 MongoDB">​</a></h4><p>默认情况下，包管理器将创建 <code>/var/lib/mongodb</code> 和 <code>/var/log/mongodb</code>，MongoDB 将使用 <code>mongodb</code> 用户帐户运行。</p>`,26)),n("p",null,[o[8]||(o[8]=s("我不会去更改这些默认设置，因为这超出了本指南的范围。有关详细信息，请查看")),t(a,{href:"https://docs.mongodb.com/manual/"},{default:e(()=>o[7]||(o[7]=[s("手册")])),_:1}),o[9]||(o[9]=s("。"))]),o[29]||(o[29]=p(`<p><code>/etc/mongod.conf</code> 中的设置在启动/重新启动 <strong>mongodb</strong> 服务实例时生效。</p><h5 id="运行-mongodb-1" tabindex="-1">运行 MongoDB <a class="header-anchor" href="#运行-mongodb-1" aria-label="Permalink to 运行 MongoDB">​</a></h5><p>要启动 mongodb 的守护进程 <code>mongod</code>，请输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo service mongod start</span></span></code></pre></div><p>现在你应该验证 <code>mongod</code> 进程是否已成功启动。此信息（默认情况下）保存在 <code>/var/log/mongodb/mongod.log</code> 中。我们来看看文件的内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo cat /var/log/mongodb/mongod.log</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/02/mongodb_org_check_logs.jpg?fit=800%2C467&amp;ssl=1" alt="Check MongoDB logs to see if the process is running properly."></p><p>只要你在某处看到：<code>[initandlisten] waiting for connections on port 27017</code>，就说明进程正常运行。</p><p><strong>注意</strong>：27017 是 <code>mongod</code> 的默认端口。</p><p>要停止/重启 <code>mongod</code>，请输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo service mongod stop</span></span>
<span class="line"><span>sudo service mongod restart</span></span></code></pre></div><p>现在，你可以通过打开 <strong>mongo shell</strong> 来使用 MongoDB：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mongo</span></span></code></pre></div><h4 id="卸载-mongodb-1" tabindex="-1">卸载 MongoDB <a class="header-anchor" href="#卸载-mongodb-1" aria-label="Permalink to 卸载 MongoDB">​</a></h4><p>运行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo service mongod stop</span></span>
<span class="line"><span>sudo apt purge mongodb-org*</span></span></code></pre></div><p>要删除<strong>数据库</strong>和<strong>日志文件</strong>（确保<strong>备份</strong>你要保留的内容！）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo rm -r /var/log/mongodb</span></span>
<span class="line"><span>sudo rm -r /var/lib/mongodb</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h3><p>MongoDB 是一个很棒的 NoSQL 数据库，它易于集成到现代项目中。我希望本教程能帮助你在 Ubuntu 上安装它！在下面的评论中告诉我们你计划如何使用 MongoDB。</p><hr>`,21)),n("p",null,[o[11]||(o[11]=s("via: ")),t(a,{href:"https://itsfoss.com/install-mongodb-ubuntu"},{default:e(()=>o[10]||(o[10]=[s("https://itsfoss.com/install-mongodb-ubuntu")])),_:1})]),n("p",null,[o[16]||(o[16]=s("作者：")),t(a,{href:"https://itsfoss.com/author/sergiu/"},{default:e(()=>o[12]||(o[12]=[s("Sergiu")])),_:1}),o[17]||(o[17]=s(" 选题：")),t(a,{href:"https://github.com/lujun9972"},{default:e(()=>o[13]||(o[13]=[s("lujun9972")])),_:1}),o[18]||(o[18]=s(" 译者：")),t(a,{href:"https://github.com/geekpi"},{default:e(()=>o[14]||(o[14]=[s("geekpi")])),_:1}),o[19]||(o[19]=s(" 校对：")),t(a,{href:"https://github.com/wxy"},{default:e(()=>o[15]||(o[15]=[s("wxy")])),_:1})]),n("p",null,[o[22]||(o[22]=s("本文由 ")),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>o[20]||(o[20]=[s("LCTT")])),_:1}),o[23]||(o[23]=s(" 原创编译，")),t(a,{href:"https://linux.cn/"},{default:e(()=>o[21]||(o[21]=[s("Linux中国")])),_:1}),o[24]||(o[24]=s(" 荣誉推出"))])])}const C=d(u,[["render",r]]);export{B as __pageData,C as default};
